import { describe, expect, test } from "vitest";
import { generate } from "../scripts/tailwind-files.ts";

// src/tailwind/ is generated by scripts/build-tailwind.ts and checked in; it must be current.

const sources = import.meta.glob<string>(
  ["../src/components/*/*.{ts,tsx}", "../src/core/*.ts", "../src/tailwind-src/*.ts"],
  { query: "?raw", import: "default", eager: true },
);
const written = import.meta.glob<string>("../src/tailwind/**/*.{ts,tsx}", {
  query: "?raw",
  import: "default",
  eager: true,
});

const under = (files: Record<string, string>, prefix: string) =>
  Object.fromEntries(
    Object.entries(files).map(([path, code]) => [path.slice(prefix.length), code]),
  );

describe("src/tailwind (generated)", () => {
  const expected = generate(under(sources, "../src/"));
  const actual = under(written, "../src/tailwind/");

  test("holds the same files as the generator makes", () => {
    expect(Object.keys(actual).sort()).toEqual(Object.keys(expected).sort());
  });

  test("is current: run `pnpm --filter owsem-ui tailwind:build` after changing a source", () => {
    for (const [path, code] of Object.entries(expected)) {
      expect(actual[path], path).toBe(code);
    }
  });

  test("starts every file with the generated header and imports no CSS", () => {
    for (const [path, code] of Object.entries(actual)) {
      expect(code.startsWith("// Generated from "), path).toBe(true);
      expect(code, path).not.toMatch(/\.css["']/);
    }
  });
});
